<script>
	import { AppBase, DialogModal, Input } from '@rdsslab/svelte-components';
	import { onDestroy, onMount } from 'svelte';
	import Logo from '../img/favicon.png';
	import { url_paths } from './utils/paths.js';

	import {
		userStore,
		storeCacheSize,
		storeEndpointOnComplete,
		storeCountResponseStatusCode,
		storeEndpointOnStart,
		storeServerDynamicInformation,
		storeServerModelChanged,
		storeIntervalTaskEvent,
		storeBotStatusChanged,
		storeBotChanged,
		statusSystemEndpointsStore,
		syncCurrentUserCtrl
	} from './utils/stores.js';

	import {
		PredictiveInput,
		OpenFusionWebsocketClient,
		Notifications
	} from '@rdsslab/svelte-components';

	import AppScreen from './widgets/basic/basic.svelte';
	import DashBoardScreen from './widgets/dashboard/dashboard.svelte';
	import AppVars from './widgets/application_variables/index.svelte';
	import Endpoints from './widgets/endpoints/index.svelte';
	import IntervalTasks from './widgets/interval_tasks/index.svelte';
	import Bots from './widgets/bots/index.svelte';
	import Logs from './widgets/logs/index.svelte';
	import ApiKeys from './widgets/apikeys/index.svelte';
	import Users from './widgets/users/index.svelte';
	import SystemUsers from './widgets/system_users/index.svelte';
	import {
		getListApps,
		changeUserPassword,
		restoreSystemEndpoints,
		GetAllAppsBackup,
		RestoreAllAppsBackup,
		GetSystemUsersList
	} from './utils/request.js';
	import {
		currentUserHasPermission,
		getDefaultEnvironment
	} from './utils/permissions.js';

	let notify = new Notifications();
	let { onexit = () => {} } = $props();
	let idapp = $state(0);
	let loading = $state(false);
	let options = $state([]);
	let menu_item_selected = $state('');
	let show_dialog_change_pwd = $state(false);

	let restore_all_file_input = $state(null);
	let loading_full_backup = $state(false);
	let loading_full_restore = $state(false);
	const wsClient = new OpenFusionWebsocketClient(url_paths.wsServerEvents);
	const defaultPasswordChange = {
		username: '',
		oldPassword: '',
		newPassword: '',
		repeatNewPassword: ''
	};

	let password_change = $state(defaultPasswordChange);

	/**
	 * Re-sincroniza el ctrl del usuario en sesión con el valor vigente en BD.
	 * Así los menús y permisos reflejan cambios hechos por un administrador sin
	 * necesidad de volver a iniciar sesión.
	 */
	async function refreshCurrentUserCtrl() {
		try {
			if (!currentUserHasPermission(currentUser, permEnv, 'users', 'read')) return;
			const users = await GetSystemUsersList();
			syncCurrentUserCtrl(users);
		} catch (error) {
			console.error('refreshCurrentUserCtrl:', error);
		}
	}

	let changepwd_compare_verify = $derived.by(() => {
		return password_change.newPassword == password_change.repeatNewPassword;
	});

	const permEnv = getDefaultEnvironment();
	const currentUser = $derived($userStore?.user);

	let menu = $derived.by(() => {
		const sections = [];

		// Application section — show if user can read apps
		if (currentUserHasPermission(currentUser, permEnv, 'apps', 'read')) {
			const appItems = [
				{
					label: 'New',
					icon: ' fa-solid fa-plus ',
					onclick: () => {
						idapp = 0;
						menu_item_selected = '/basic';
					}
				},
				{
					label: 'Dashboard',
					icon: ' fa-solid fa-chart-area ',
					onclick: () => {
						menu_item_selected = '/dashboard';
					}
				},
				{
					label: 'Basic',
					icon: ' fa-solid fa-file ',
					onclick: () => {
						menu_item_selected = '/basic';
					}
				}
			];

			if (currentUserHasPermission(currentUser, permEnv, 'endpoints', 'read')) {
				appItems.push({
					label: 'Endpoints',
					icon: ' fa-solid fa-network-wired ',
					onclick: () => {
						menu_item_selected = '/endpoints';
					}
				});
			}
			if (currentUserHasPermission(currentUser, permEnv, 'appvars', 'read')) {
				appItems.push({
					label: 'Variables',
					icon: ' fa-solid fa-square-root-variable ',
					onclick: () => {
						menu_item_selected = '/appvars';
					}
				});
			}
			if (currentUserHasPermission(currentUser, permEnv, 'apiclients', 'read')) {
				appItems.push({
					label: 'API Keys',
					icon: ' fa-solid fa-key ',
					onclick: () => {
						menu_item_selected = '/apikeys';
					}
				});
			}
			if (currentUserHasPermission(currentUser, permEnv, 'bots', 'read')) {
				appItems.push({
					label: 'Bots',
					icon: ' fa-solid fa-robot ',
					onclick: () => {
						menu_item_selected = '/bots';
					}
				});
			}
			if (currentUserHasPermission(currentUser, permEnv, 'interval_tasks', 'read')) {
				appItems.push({
					label: 'Tasks',
					icon: ' fa-solid fa-list-check ',
					onclick: () => {
						menu_item_selected = '/interval_tasks';
					}
				});
			}
			// Recurso de logs a nivel de aplicación (mismo gate que apps: no existe permiso
			// granular 'logs' todavía en el backend).
			appItems.push({
				label: 'Logs',
				icon: ' fa-solid fa-scroll ',
				onclick: () => {
					menu_item_selected = '/logs';
				}
			});

			sections.push({ title: 'Application', items: appItems });
		}

		// Administration section
		const adminItems = [];
		if (currentUserHasPermission(currentUser, permEnv, 'users', 'read')) {
			adminItems.push({
				label: 'System Users',
				icon: ' fa-solid fa-user-gear ',
				onclick: () => {
					menu_item_selected = '/system-users';
				}
			});
		}
		if (currentUserHasPermission(currentUser, permEnv, 'apiclients', 'read')) {
			adminItems.push({
				label: 'API Clients',
				icon: ' fa-solid fa-users ',
				onclick: () => {
					menu_item_selected = '/users';
				}
			});
		}
		if (adminItems.length > 0) {
			sections.push({ title: 'Administration', items: adminItems });
		}

		return sections;
	});

	async function getListAppsInternal() {
		try {
			loading = true;
			let apps = await getListApps($userStore.token);
			if (apps && Array.isArray(apps) && apps.length > 0) {
				options = apps.map((item) => {
					return { name: item.app, value: item.idapp };
				});
			} else {
				options = [];
			}

			let status_sys_endp = await restoreSystemEndpoints(false, $userStore.token);
			statusSystemEndpointsStore.set(status_sys_endp);
		} catch (error) {
			console.error(error);
			notify.push({ message: error.message, color: 'danger' });
		} finally {
			loading = false;
		}
	}

	function downloadFullBackupFile(full_backup) {
		const now = new Date();
		const year = now.getFullYear();
		const month = String(now.getMonth() + 1).padStart(2, '0');
		const day = String(now.getDate()).padStart(2, '0');
		const hours = String(now.getHours()).padStart(2, '0');
		const minutes = String(now.getMinutes()).padStart(2, '0');

		const jsonString = JSON.stringify(full_backup, null, 2);
		const blob = new Blob([jsonString], { type: 'application/json' });
		const url = window.URL.createObjectURL(blob);
		const a = document.createElement('a');
		a.href = url;
		a.download = `apps_full_${year}${month}${day}_${hours}${minutes}.json`;
		a.click();
		window.URL.revokeObjectURL(url);
	}

	async function backupAllApps() {
		try {
			loading_full_backup = true;
			const full_backup = await GetAllAppsBackup($userStore.token);

			if (!full_backup || !Array.isArray(full_backup.apps)) {
				throw new Error('Invalid full backup received from server');
			}

			downloadFullBackupFile(full_backup);
			notify.push({
				message: `Full backup downloaded (${full_backup.count} applications)`,
				color: 'success'
			});
		} catch (error) {
			console.error(error);
			notify.push({ message: error.message, color: 'danger' });
		} finally {
			loading_full_backup = false;
		}
	}

	async function onRestoreAllFileSelected(event) {
		const selectedFile = event.target.files[0];

		if (!selectedFile) {
			notify.push({ message: 'Invalid JSON file', color: 'warning' });
			return;
		}

		const reader = new FileReader();

		reader.onload = async (e) => {
			let full_backup;

			try {
				full_backup = JSON.parse(e.target.result);
			} catch (error) {
				console.error('Error parsing the JSON file:', error);
				notify.push({ message: error.message, color: 'danger' });
				return;
			}

			if (!full_backup || (!Array.isArray(full_backup) && !Array.isArray(full_backup.apps))) {
				notify.push({
					message: 'Invalid full backup file: expected an object with an apps array',
					color: 'danger'
				});
				return;
			}

			if (
				!confirm(
					'This action will replace the data of ALL applications included in the backup. Do you want to continue?'
				)
			) {
				return;
			}

			try {
				loading_full_restore = true;
				const summary = await RestoreAllAppsBackup(full_backup);

				if (summary && typeof summary.restored === 'number') {
					if (summary.failed > 0) {
						notify.push({
							message: `Restore finished with errors: ${summary.restored} restored, ${summary.failed} failed`,
							color: 'warning'
						});
					} else {
						notify.push({
							message: `All applications restored (${summary.restored})`,
							color: 'success'
						});
					}
					await getListAppsInternal();
				} else {
					notify.push({ message: 'Applications not restored', color: 'danger' });
				}
			} catch (error) {
				console.error(error);
				notify.push({ message: error.message, color: 'danger' });
			} finally {
				loading_full_restore = false;
				event.target.value = '';
			}
		};

		reader.readAsText(selectedFile);
	}

	onMount(async () => {
		await getListAppsInternal();
		await refreshCurrentUserCtrl();

		notify.push({ message: 'Welcome ', color: 'success' });

		wsClient.connect();
		wsClient.on('open', () => {
			wsClient.subscribe('/server/events');
		});

		wsClient.on('message', (m) => {
			//console.log('XXXXX >>>>> ', m);

			if (m && m.event_name == 'system_information') {
				storeServerDynamicInformation.set(m.data);
			} else if (m && m.event_name == 'interval_task') {
				// Debe ir antes del filtro por idapp: el evento trae idapp, pero el widget de
				// tareas necesita verlo aunque el usuario esté en otra aplicación abierta.
				storeIntervalTaskEvent.set({ ...m.data, ts: m.timestamp });
			} else if (m && m.event_name == 'bot_status_changed') {
				// Runtime status change (STARTING, RUNNING, STOPPED, QUARANTINED, etc.).
				storeBotStatusChanged.set({ ...m.data, ts: m.timestamp });
			} else if (m && m.event_name == 'bot_changed') {
				// Structural change (create/edit/delete): the list must reload.
				storeBotChanged.set({ ...m.data, ts: m.timestamp });
			} else if (m && m.data?.idapp == idapp) {
				if (m && (m.event_name == 'cache_set' || m.event_name == 'cache_released')) {
					storeCacheSize.update((value) => {
						value[m.data.idendpoint] = m.data.size.endpoint;

						return value;
					});
				} else if (m && m.event_name == 'request_completed') {
					let data1 = m.data;
					data1.dateTime = m.timestamp;
					console.log('request_completed >>>>> ', data1);
					storeEndpointOnComplete.set(data1);

					storeCountResponseStatusCode.update((value) => {
						if (value[m.data.idendpoint] === undefined) {
							value[m.data.idendpoint] = {};
						}

						let current = value?.[m.data.idendpoint]?.[m.data.statusCode];
						value[m.data.idendpoint][m.data.statusCode] =
							current !== undefined && current !== null ? Number(current) + 1 : 1;

						return value;
					});
				} else if (m && m.event_name == 'request_start') {
					storeEndpointOnStart.set({ idendpoint: m.data?.idendpoint, ts: new Date() });
				}
			} else if (m && m.event_name == 'database_hook') {
				console.log('database_hook >>>>> ', m);
				/*
{
    "event_name": "database_hook",
    "timestamp": "2026-06-10T03:46:59.347Z",
    "data": {
        "host": ".",
        "database": "temporales/ofapi4.sqlite",
        "schema": "",
        "model": "ofapi_appvars",
        "action": "afterUpsert",
        "data": {
            "value": "ok_2026-05-21",
            "idvar": "50b50ea2-5d1d-4559-9caa-e267bd124afd",
            "idapp": "c4ca4238-a0b9-2382-0dcc-509a6f75849b",
            "environment": "prd",
            "name": "TEST_UPSERT_WRITE",
            "type": "string"
        }
    }
}
*/

				storeServerModelChanged.set({
					ts: m.timestamp,
					action: m.data.action,
					model: m.data.model,
					idapp: m.data.data?.idapp
				});
			}
		});
	});

	onDestroy(() => {
		wsClient.close();
	});
</script>

{#snippet logoIcon()}
	<img
		src={Logo}
		alt="Open Fusion API"
		style="width: 32px; height: 32px; object-fit: contain; display: block; margin: auto;"
	/>
{/snippet}

{#snippet user()}
	<input
		hidden
		type="file"
		accept=".json"
		bind:this={restore_all_file_input}
		onchange={onRestoreAllFileSelected}
	/>
	<button
		class="button is-small is-info is-outlined"
		title="Download a full backup of all applications"
		disabled={loading_full_backup}
		onclick={backupAllApps}
	>
		<span class="icon is-small">
			<i class="fa-solid {loading_full_backup ? 'fa-spinner fa-spin' : 'fa-download'}"></i>
		</span>
		<span>Backup All</span>
	</button>
	<button
		class="button is-small is-warning is-outlined"
		title="Restore all applications from a full backup file"
		disabled={loading_full_restore}
		onclick={() => restore_all_file_input.click()}
	>
		<span class="icon is-small">
			<i class="fa-solid {loading_full_restore ? 'fa-spinner fa-spin' : 'fa-upload'}"></i>
		</span>
		<span>Restore All</span>
	</button>
	<div class="dropdown is-hoverable">
		<div class="dropdown-trigger">
			<button
				title={$statusSystemEndpointsStore.message}
				class="button is-small {$statusSystemEndpointsStore.valid ? '' : 'is-danger'} "
				aria-haspopup="true"
				aria-controls="dropdown-menu3"
			>
				<span class="icon is-small">
					{#if $statusSystemEndpointsStore.valid}
						<i class="fa-solid fa-check"></i>
					{:else}
						<i class="fa-solid fa-triangle-exclamation fa-fade"></i>
					{/if}
				</span>
				<span> System Endpoints {$statusSystemEndpointsStore.valid ? 'Ready' : 'Error'} </span>
				<span class="icon is-small">
					<i class="fa-solid fa-angle-down" aria-hidden="true"></i>
				</span>
			</button>
		</div>
		<div class="dropdown-menu" role="menu">
			<div class="dropdown-content">
				<!-- svelte-ignore a11y_invalid_attribute -->
				<a
					href="#"
					class="dropdown-item"
					onclick={async () => {
						let status_sys_endp = await restoreSystemEndpoints(true, $userStore.token);
						statusSystemEndpointsStore.set(status_sys_endp);
					}}
				>
					<div class="icon-text">
						<span class="icon">
							<i class="fa-solid fa-rotate-left"></i>
						</span>
						<span> Restore </span>
					</div>
				</a>
			</div>
		</div>
	</div>
	<div class="dropdown is-hoverable">
		<div class="dropdown-trigger">
			<button
				class="button is-small is-success is-outlined"
				aria-haspopup="true"
				aria-controls="dropdown-menu3"
			>
				<span class="icon is-small">
					<i class="fa-solid fa-user"></i>
				</span>
				<span> {$userStore?.user?.username}</span>
				<span class="icon is-small">
					<i class="fa-solid fa-angle-down" aria-hidden="true"></i>
				</span>
			</button>
		</div>
		<div class="dropdown-menu" role="menu">
			<div class="dropdown-content">
				<!-- svelte-ignore a11y_invalid_attribute -->
				<a
					href="#"
					class="dropdown-item"
					onclick={() => {
						show_dialog_change_pwd = true;
						password_change = { ...defaultPasswordChange };
						password_change.username = $userStore?.user?.username || '';
					}}
				>
					<div class="icon-text">
						<span class="icon">
							<i class="fa-solid fa-key"></i>
						</span>
						<span>Password</span>
					</div>
				</a>

				<hr class="dropdown-divider" />

				<!-- svelte-ignore a11y_click_events_have_key_events -->
				<!-- svelte-ignore a11y_no_static_element_interactions -->
				<div
					class="dropdown-item"
					onclick={() => {
						userStore.set({});
						onexit();
					}}
				>
					<div class="icon-text">
						<span class="icon has-text-danger">
							<i class="fa-solid fa-arrow-right-from-bracket"></i>
						</span>
						<span>Logout</span>
					</div>
				</div>
			</div>
		</div>
	</div>
{/snippet}

{#snippet select_app()}
	<div class="is-flex is-align-items-center" style="gap: 0.5rem;">
		<PredictiveInput
			label="Application"
			classLabel="is-small"
			classInput="is-small"
			bind:options
			onselect={async (e) => {
				if ($userStore) {
					// Limpiar stores de la app anterior antes de cargar la nueva
					storeCacheSize.set({});
					storeEndpointOnComplete.set({});
					storeCountResponseStatusCode.set({});
					storeEndpointOnStart.set({});
					idapp = e.value;
				} else {
					notify.push({ message: 'You do not have authorization', color: 'warning' });
				}
			}}
		/>
		{#if loading}
			<span class="icon is-small has-text-grey">
				<i class="fa-solid fa-spinner fa-spin"></i>
			</span>
		{/if}
	</div>
{/snippet}

<AppBase
	{logoIcon}
	logoText="OpenFusionAPI"
	{menu}
	topLeftNavBar={[select_app]}
	topRightNavBar={[user]}
>
	{#key idapp}
		{#if menu_item_selected == '/basic'}
			<AppScreen
				{idapp}
				onsavedeploy={async () => {
					await getListAppsInternal();
				}}
			></AppScreen>
		{:else if menu_item_selected == '/appvars'}
			<AppVars {idapp}></AppVars>
		{:else if menu_item_selected == '/endpoints'}
			<Endpoints {idapp}></Endpoints>
		{:else if menu_item_selected == '/interval_tasks'}
			<IntervalTasks {idapp}></IntervalTasks>
		{:else if menu_item_selected == '/apikeys'}
			<ApiKeys bind:idapp></ApiKeys>
		{:else if menu_item_selected == '/bots'}
			<Bots bind:idapp></Bots>
		{:else if menu_item_selected == '/system-users'}
			<SystemUsers></SystemUsers>
		{:else if menu_item_selected == '/users'}
			<Users></Users>
		{:else if menu_item_selected == '/logs'}
			<Logs {idapp}></Logs>
		{:else}
			<DashBoardScreen {idapp}></DashBoardScreen>
		{/if}
	{/key}</AppBase
>

<DialogModal
	title={titleModal}
	body={bodyDialogModal}
	onaccept={async () => {
		if (password_change.newPassword == password_change.repeatNewPassword) {
			let result = await changeUserPassword(password_change, $userStore.token);
			if (result.success) {
				password_change = { ...defaultPasswordChange };
				show_dialog_change_pwd = false;
				notify.push({ message: 'Successful update', color: 'success' });
			} else {
				notify.push({ message: result.error, color: 'danger' });
			}
		} else {
			notify.push({ message: 'You must repeat the new password twice.', color: 'danger' });
		}
	}}
	oncancel={() => {
		password_change = { ...defaultPasswordChange };
	}}
	bind:show={show_dialog_change_pwd}
>
	{#snippet titleModal()}
		<span>{`Change Password: ${password_change.username}`}</span>
	{/snippet}

	{#snippet bodyDialogModal()}
		<Input label="Current password" type="password" bind:value={password_change.oldPassword}
		></Input>
		<Input label="New Password" type="password" bind:value={password_change.newPassword}></Input>
		<Input
			label="Repeat new Password"
			type="password"
			bind:value={password_change.repeatNewPassword}
		></Input>
		<div>
			{#if !changepwd_compare_verify}
				<span class="icon-text has-text-warning is-small">
					<span class="icon">
						<i class="fas fa-exclamation-triangle"></i>
					</span>
					<span>You must repeat the new password twice.</span>
				</span>
			{/if}
		</div>
	{/snippet}
</DialogModal>
